draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  // book
  ctx.fillStyle = '#964B00';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);
  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-130);
  ctx.lineTo(W/2, H/2-50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-70);
  ctx.lineTo(W/2-30, H/2-90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-70);
  ctx.lineTo(W/2+30, H/2-90);
  ctx.stroke();
  // applying wisdom
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Applying Wisdom', W/2, H/2+20);
  ctx.fillText('Lessons Learned', W/2, H/2+50);
  // animation
  ctx.save();
  ctx.translate(W/2, H/2-150);
  ctx.rotate(Math.sin(t));
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(50, 0);
  ctx.stroke();
  ctx.restore();
  ctx.restore();
}
